result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/queue.mjs", "content": "export class JobQueue {
  constructor() {
    this.jobs = [];
    this.done = [];
    this.running = false;
    this.#idleResolvers = [];
  }

  push(job) {
    this.jobs.push(job);
    this.#kick();
  }

  /**
   * Resolves when the queue is empty and all pushed jobs have settled.
   * Safe to call at any time; if the queue is already idle, resolves immediately.
   */
  idle() {
    if (!this.running && this.jobs.length === 0) return Promise.resolve();
    return new Promise(resolve => this.#idleResolvers.push(resolve));
  }

  #idleResolvers;

  #kick() {
    if (this.running) return;
    this.running = true;
    setTimeout(() => this.#drain(), 0);
  }

  async #drain() {
    while (this.jobs.length > 0) {
      const job = this.jobs.shift();
      try {
        const result = await job();
        this.done.push(result);
      } catch (err) {
        // A rejecting job must not wedge the queue: record it and continue.
        this.done.push({ error: err });
      }
    }
    this.running = false;
    const resolvers = this.#idleResolvers;
    this.#idleResolvers = [];
    for (const resolve of resolvers) resolve();
  }
}
"})
