import assert from "node:assert";
import { JobQueue } from "./queue.mjs";

test("processes both jobs in order", async () => {
  const q = new JobQueue();
  q.push(async () => { await new Promise(r => setTimeout(r, 10)); return "a"; });
  q.push(async () => "b");
  await q.idle();
  assert.deepEqual(q.done, ["a", "b"]);
});

test("jobs pushed while draining still run before idle resolves", async () => {
  const q = new JobQueue();
  let drained = false;
  q.push(async () => {
    // Pushed from inside a running job — must be picked up by the same drain.
    q.push(async () => { await new Promise(r => setTimeout(r, 5)); drained = true; return "late"; });
    return "first";
  });
  await q.idle();
  assert.equal(drained, true);
  assert.deepEqual(q.done, ["first", "late"]);
});

test("a rejecting job is recorded as {error} and does not wedge the queue", async () => {
  const q = new JobQueue();
  q.push(async () => { throw new Error("boom"); });
  q.push(async () => "after-failure");
  await q.idle();
  assert.equal(q.done.length, 2);
  assert.ok(q.done[0] instanceof Object && "error" in q.done[0]);
  assert.match(q.done[0].error.message, /boom/);
  assert.equal(q.done[1], "after-failure");

  // Queue is reusable after the failure.
  q.push(async () => "recovered");
  await q.idle();
  assert.deepEqual(q.done.slice(2), ["recovered"]);
});
"})
